    int numVertices = target.getNumVertices();
    int numEdges = (int)Math.ceil(numVertices / 2.0);
    List<GraphEdge> edges = new ArrayList<GraphEdge>();
    HashMap<Integer, GraphNode> nodeMap = new HashMap<Integer, GraphNode>();

    // Iterate over the target graph vertices and add them to the new graph
    for(V vertex : target.getVertices()) {
        int id = target.getVertexId(vertex);
        if(!nodeMap.containsKey(id)) {
            GraphNode loc0 = new GraphNode(id);
            nodeMap.put(id, loc0);
            numVertices++;
