public static LinkedBuffer writeUTF8(CharSequence str, WriteSession session, LinkedBuffer lb) {
    // Iterate over the characters in the string
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);

        // Check if the character is a high surrogate
        if (Character.isHighSurrogate(c)) {
            // If it is, get the next character in the string and check if it is a low surrogate
            if (i + 1 < str.length()) {
                char d = str.charAt(i + 1);
                if (Character.isLowSurrogate(d)) {
                    // If it is, write the surrogate pair to the buffer
                    lb.append(c);
                    lb.append(d);
                    i++;
                }
                else {
                    // If it is not, throw an exception
                    throw new IllegalArgumentException("Invalid UTF8 encoding");
                }
            }
            else {
                // If there are not enough characters in the string, throw an exception
                throw new IllegalArgumentException("Invalid UTF8 encoding");
            }
        }
        else {
            // If the character is not a high surrogate, write it to the buffer as is
            lb.append(c);
        }
    }
    return lb;
}

