public static String unescapeJava(String str) throws Exception {
  if (str == null) {
    return null;
  }

  // first pass to replace escaped single quote \' with single quote '
  str = StringUtils.replace(str, "\\'", "'");

  // second pass to replace escaped backslash \\ with backslash \
  str = StringUtils.replace(str, "\\\\", "\\");

  // third pass to replace \n with newline character
