/**
* Computes the minimal separators of an edge in the neighborhood of a vertex
* @param edge the edge in the neighborhood of which the minimal separators are to be computed
* @return the list of minimal separators of the given edge
*/
private List<Pair<Integer, Integer>> getMinimalSeparators(E edge) {
    // Initialize the list of minimal separators
    List<Pair<Integer, Integer>> minimalSeparators = new ArrayList<>();

    // Add the source and target vertices of the edge to the minimal separators
    minimalSeparators.add(new Pair<>(edge.getSource(), edge.getTarget()));

    // Iterate over the neighbors of the source and target vertices of the edge
    for (V neighbor : graph.getNeighbors(edge.getSource())) {
        if (!edge.getTarget().equals(neighbor)) {
            // Add the neighbor to the minimal separators
            minimalSeparators.add(new Pair<>(neighbor, edge.getTarget()));
        }
    }

    // Sort the minimal separators by their first component
    minimalSeparators.sort((a, b) -> a.getFirst().compareTo(b.getFirst()));

    return minimalSeparators;
}

