for (ThreadSnapshotEvent event : snapshotBuilder.getEvents()) {
long eventTime = event.getTimestamp().getTime();
if (eventTime > currentTime) {
if (lastSnapshotTime < eventTime) {
lastSnapshotTime = eventTime;
}
currentTime = Math.min(lastSnapshotTime + SNAPSHOT_DURATION, eventTime);
snapshot = snapshots.get((int)(currentTime - timeRange.getStartTime().getTime()) / SNAPSHOT_DURATION);
